// The pets seen from behind, for the arcade (art: back-art.js, generated by tools/make-back-sprites.mjs). The pure parts (the pixel list of a pose) are tested;
// `backCanvas` paints one into a cached canvas. A pose moves the art a few pixels: the whole pet drops a pixel and the head sways a pixel to one side, which
// with three frames makes the run's bob; `lean` (-1, 0, 1) tips the head into a lane change.
import { BACK_ART, PALETTE, ELDER_PALETTE } from './back-art.js';
import { STAGES } from '../protocol.js';

export const BACK_CELL = 32;
export const HEAD_ROWS = 15;                       // the rows above this move with the head's sway
export const FRAMES = 3;
/** Frame order of the run: 0 1 0 2 (a rest, a step each way). */
export const RUN_SEQ = [0, 1, 0, 2];
const POSES = [{ bob: 0, sway: 0 }, { bob: 1, sway: -1 }, { bob: 1, sway: 1 }];

/** The art rows and palette of a pet: the elder is the adult in its paler palette. */
export function backArt(species, stage) {
  const name = STAGES[stage];
  const base = name === 'elder' ? 'adult' : name;
  const rows = BACK_ART[`${species}-${base}`];
  if (!rows) return null;
  return { rows, palette: (name === 'elder' ? ELDER_PALETTE : PALETTE)[species] };
}

/** The rows of a pose: shifted down by `bob` pixels, the head rows sideways by `sway + lean` pixels. Nothing leaves the 32 x 32 cell. */
export function poseRows(rows, frame = 0, lean = 0) {
  const { bob, sway } = POSES[((frame % FRAMES) + FRAMES) % FRAMES];
  const shift = Math.max(-2, Math.min(2, sway + lean));
  const blank = '.'.repeat(BACK_CELL);
  const out = [];
  for (let y = 0; y < BACK_CELL; y++) {
    const src = rows[y - bob];
    if (src === undefined) { out.push(blank); continue; }
    const dx = y - bob < HEAD_ROWS ? shift : 0;
    out.push(dx === 0 ? src : dx > 0 ? ('.'.repeat(dx) + src).slice(0, BACK_CELL) : (src.slice(-dx) + '.'.repeat(-dx)));
  }
  return out;
}

/** The pixels of rows as [{ x, y, color }] (everything but '.'). */
export function pixelsOf(rows, palette) {
  const px = [];
  rows.forEach((row, y) => { for (let x = 0; x < row.length; x++) if (row[x] !== '.') px.push({ x, y, color: palette[row[x]] }); });
  return px;
}

const cache = new Map();
/** A 32 x 32 canvas with the pet from behind in `frame` and `lean`. */
export function backCanvas(species, stage, frame = 0, lean = 0) {
  const key = `${species}|${stage}|${frame}|${lean}`;
  let c = cache.get(key);
  if (c) return c;
  const art = backArt(species, stage);
  c = document.createElement('canvas');
  c.width = c.height = BACK_CELL;
  if (art) {
    const ctx = c.getContext('2d');
    for (const p of pixelsOf(poseRows(art.rows, frame, lean), art.palette)) { ctx.fillStyle = p.color; ctx.fillRect(p.x, p.y, 1, 1); }
  }
  cache.set(key, c);
  return c;
}
